    11→/**
    12→ * 👮‍♂️ Middleware que protege las rutas relacionadas con cambio de rol y empresa.
    13→ *
    14→ * Cada usuario debe estar relacionado con su rol por medio de ambas tablas, por medio de la tabla
    15→ * `empresas_usuarios` se relaciona al usuario con el rol y la empresa y por medio de
    16→ * `model_has_roles` se relaciona al usuario con el rol directamente y se define a traves de que rol
    17→ * está interactuando el usuario con la aplicación en cada momento por medio del campo `active`, un
    18→ * usuario no debe tener mas de un rol activo.
    19→ *
    20→ * Los unicos usuarios que no están obligados a seguir esta regla son los usuarios con rol
    21→ * `Evaluado`, estos usuarios pueden estár relacionados con un rol por medio de la tabla
    22→ * `model_has_roles` sin que exista la relación en la tabla `empresas_usuarios`, esto significa que
    23→ * un usuario con rol `Evaluado` puede estár relacionado con su rol sin estar relacionado con una
    24→ * empresa en particular.
    25→ *
    26→ * @author Fahibram Cárcamo
    27→ */
    28→class CambioRolEmpresaMiddleware
    29→{
    30→    use SesionTrait;
    31→
    32→    /**
    33→     * Constructor.
    34→     *
    35→     * @param RolRepository $rol_repositorio Repositorio de roles
    36→     * @return void
    37→     * @author Fahibram Cárcamo
    38→     */
    39→    public function __construct(protected RolRepository $rol_repositorio) {}
    40→
    41→    /**
    42→     * Manejar la solicitud http entrante.
    43→     *
    44→     * @param Closure(Request): (Response) $next
    45→     * @author Fahibram Cárcamo
    46→     */
    47→    public function handle(Request $request, Closure $next): Response {
    48→        // Condición para usuario con rol superadmin.
    49→        if (
    50→            ($this->existeEnSesion('rol_suplantado') && filter_var($this->obtenerDeSesion('rol_suplantado'), FILTER_VALIDATE_BOOLEAN) === true) ||
    51→            ($this->existeEnSesion('rol_id') && $this->obtenerDeSesion('rol_id') === $this->rol_repositorio::ROL_SUPERADMIN_ID)
    52→        ) {
    53→            return $next($request);
    54→        }
    55→
    56→        // Condición para usuario suplantado.
    57→        if ($this->existenDatosSuplantacionSesion()) {
    58→            if ($this->obtenerDeSesion('rol_original_id') === $this->rol_repositorio::ROL_SUPERADMIN_ID) {
    59→                return $next($request);
    60→            }
    61→
    62→            return redirect()->route('inicio');
    63→        }
    64→
    65→        // Condición para usuario con mas de un rol en una o varias empresas.
    66→        if ($this->existeEnSesion('cambio_rol_empresa')) {
    67→            return filter_var($this->obtenerDeSesion('cambio_rol_empresa'), FILTER_VALIDATE_BOOLEAN) === true
    68→                ? $next($request)
    69→                : redirect()->route('inicio');
    70→        }
    71→
    72→        return redirect()->route('inicio');
    73→    }
    74→}
